function normalizeItem(raw) {
  const source = raw && typeof raw === 'object' ? raw : {};
  const title = String(source.title || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  const link = String(source.link || '').trim();
  const id = String(source.guid || source.link || title).trim();
  const snippet = String(source.contentSnippet || source.content || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 240);
  return { id: id, title: title, link: link, snippet: snippet };
}

function keywordHits(item, keywords) {
  const title = String((item && item.title) || '');
  const snippet = String((item && item.snippet) || '');
  const link = String((item && item.link) || '');
  const hay = (title + '\n' + snippet + '\n' + link).toLowerCase();
  const hits = [];
  const list = Array.isArray(keywords) ? keywords : [];
  for (let i = 0; i < list.length; i++) {
    const needle = String(list[i] || '').toLowerCase();
    if (needle && hay.indexOf(needle) !== -1) hits.push(needle);
  }
  return hits;
}

const DEFAULT_KEYWORDS = ['engineer', 'developer', 'python', 'remote'];

if (typeof $input === 'undefined') {
  return { normalizeItem: normalizeItem, keywordHits: keywordHits, DEFAULT_KEYWORDS: DEFAULT_KEYWORDS };
}

const matches = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const normalized = normalizeItem(items[i].json || {});
  const hits = keywordHits(normalized, DEFAULT_KEYWORDS);
  if (hits.length && normalized.id) {
    matches.push({
      id: normalized.id,
      title: normalized.title,
      link: normalized.link,
      snippet: normalized.snippet,
      keywords: hits,
    });
  }
}
return [{
  json: {
    matches: matches,
    count: matches.length,
    hasItems: matches.length ? 'yes' : 'no',
  },
}];

function selectUnseen(items, seen) {
  const unseen = [];
  const map = seen && typeof seen === 'object' ? seen : {};
  const list = Array.isArray(items) ? items : [];
  for (let i = 0; i < list.length; i++) {
    const item = list[i];
    const id = String((item && item.id) || '');
    if (!id || Object.prototype.hasOwnProperty.call(map, id)) continue;
    unseen.push(item);
  }
  return unseen;
}

if (typeof $input === 'undefined') {
  return { selectUnseen: selectUnseen };
}

const incoming = $input.first().json || {};
const staticData = $getWorkflowStaticData('global');
const unseen = selectUnseen(incoming.matches || [], staticData.sent || {});
return [{
  json: {
    matches: unseen,
    count: unseen.length,
    hasItems: unseen.length ? 'yes' : 'no',
  },
}];

function buildDigest(items, generatedAt) {
  const list = Array.isArray(items) ? items : [];
  const lines = ['Job digest', 'Items: ' + list.length, 'Generated: ' + String(generatedAt || ''), ''];
  const shown = list.slice(0, 20);
  for (let i = 0; i < shown.length; i++) {
    const item = shown[i];
    lines.push('- ' + String(item.title || 'untitled'));
    if (item.link) lines.push('  ' + String(item.link));
    if (item.keywords && item.keywords.length) lines.push('  keywords: ' + item.keywords.join(', '));
  }
  if (!list.length) lines.push('No new items.');
  const ids = [];
  for (let i = 0; i < list.length; i++) {
    const id = String((list[i] && list[i].id) || '');
    if (id) ids.push(id);
  }
  return {
    subject: 'Job digest (' + list.length + ')',
    text: lines.join('\n'),
    ids: ids,
    count: list.length,
  };
}

if (typeof $input === 'undefined') {
  return { buildDigest: buildDigest };
}

const incoming = $input.first().json || {};
const digest = buildDigest(incoming.matches || [], new Date().toISOString());
return [{ json: digest }];

function markSent(seen, ids) {
  const next = {};
  const source = seen && typeof seen === 'object' ? seen : {};
  const keys = Object.keys(source);
  for (let i = 0; i < keys.length; i++) next[keys[i]] = true;
  const list = Array.isArray(ids) ? ids : [];
  for (let i = 0; i < list.length; i++) {
    const id = String(list[i] || '');
    if (id) next[id] = true;
  }
  return next;
}

if (typeof $input === 'undefined') {
  return { markSent: markSent };
}

const built = $('Build Digest Email').first().json || {};
const staticData = $getWorkflowStaticData('global');
const next = markSent(staticData.sent, built.ids || []);
staticData.sent = next;
return [{ json: { marked: (built.ids || []).length, hasItems: 'yes' } }];
